-- One station's explicitly approved future print; no carrier calls, no device-success claim.
CREATE TABLE packed_label_print_previews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),actor_id uuid NOT NULL REFERENCES users(id),client_key uuid NOT NULL,request_hash text NOT NULL,scope_hash text NOT NULL,expected_version bigint NOT NULL CHECK(expected_version>=0),settings jsonb NOT NULL,snapshot jsonb NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),commit_key uuid,configuration_id uuid,UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key));
CREATE TABLE packed_label_print_configurations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),station_id uuid NOT NULL,version bigint NOT NULL CHECK(version>0),approved_by uuid NOT NULL REFERENCES users(id),preview_id uuid NOT NULL,enabled boolean NOT NULL,settings jsonb NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,station_id,version),FOREIGN KEY(tenant_id,station_id) REFERENCES packing_stations(tenant_id,id),FOREIGN KEY(tenant_id,preview_id) REFERENCES packed_label_print_previews(tenant_id,id));
ALTER TABLE packed_label_print_previews ADD FOREIGN KEY(tenant_id,configuration_id) REFERENCES packed_label_print_configurations(tenant_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE packed_label_print_intents(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),receipt_id uuid NOT NULL,order_id uuid NOT NULL,station_id uuid NOT NULL,configuration_id uuid NOT NULL,approved_by uuid NOT NULL REFERENCES users(id),state text NOT NULL CHECK(state IN('waiting','queued','blocked')),reason text,preview_key uuid NOT NULL,queue_key uuid NOT NULL,job_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,receipt_id),UNIQUE(tenant_id,job_id),FOREIGN KEY(tenant_id,receipt_id,order_id) REFERENCES packing_receipts(tenant_id,id,order_id),FOREIGN KEY(tenant_id,configuration_id) REFERENCES packed_label_print_configurations(tenant_id,id),FOREIGN KEY(tenant_id,station_id) REFERENCES packing_stations(tenant_id,id),FOREIGN KEY(tenant_id,job_id) REFERENCES print_jobs(tenant_id,id) DEFERRABLE INITIALLY DEFERRED,CHECK((state='queued')=(job_id IS NOT NULL)));
CREATE TABLE packed_label_print_admissions(tenant_id uuid NOT NULL,intent_id uuid NOT NULL,preview_id uuid NOT NULL,approved_by uuid NOT NULL,top_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),started_at timestamptz NOT NULL DEFAULT transaction_timestamp(),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,intent_id),UNIQUE(tenant_id,preview_id),FOREIGN KEY(tenant_id,intent_id) REFERENCES packed_label_print_intents(tenant_id,id),FOREIGN KEY(tenant_id,preview_id) REFERENCES print_label_previews(tenant_id,id));
CREATE TABLE packed_label_print_manifest(singleton boolean PRIMARY KEY CHECK(singleton),fingerprint text NOT NULL);
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['packed_label_print_previews','packed_label_print_configurations','packed_label_print_intents','packed_label_print_admissions'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',n);
 EXECUTE format($policy$CREATE POLICY tenant_scope ON %I TO dyna_app USING(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid)$policy$,n);
 EXECUTE format('CREATE POLICY owner_scope ON %I TO %I USING(true) WITH CHECK(true)',n,current_user);
 EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,dyna_app',n);END LOOP;END $$;
GRANT SELECT ON packed_label_print_configurations,packed_label_print_intents TO dyna_app;
REVOKE ALL ON packed_label_print_manifest FROM PUBLIC,dyna_app;
CREATE FUNCTION packed_label_print_require(uid uuid,writing boolean,pin boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE g jsonb;BEGIN
 IF packed_label_print_guards() IS NOT TRUE THEN RAISE EXCEPTION 'Automatyczny druk jest niekompletny' USING ERRCODE='55000';END IF;
 g:=print_job_access(uid,NULL,writing,pin);
 IF (g->>'allowed')::boolean IS NOT TRUE OR (writing AND g->>'role' IS DISTINCT FROM 'admin') THEN RAISE EXCEPTION 'Wymagany bieżący administrator drukowania' USING ERRCODE='42501';END IF;
 PERFORM label_print_require(uid,NULL,writing);
END $$;
CREATE FUNCTION packed_label_print_configuration_frame(v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE st packing_stations;p print_printers;t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR (v-ARRAY['station_id','station_version','printer_id','printer_version','copies','enabled'])<>'{}'::jsonb OR jsonb_typeof(v->'enabled') IS DISTINCT FROM 'boolean' OR jsonb_typeof(v->'copies') IS DISTINCT FROM 'number' OR (v->>'copies')!~'^[1-9][0-9]*$' OR (v->>'copies')::int NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'Niepoprawne ustawienia przyszłego druku' USING ERRCODE='23514';END IF;
 SELECT * INTO st FROM packing_stations WHERE tenant_id=t AND id=(v->>'station_id')::uuid FOR UPDATE;
 SELECT * INTO p FROM print_printers WHERE tenant_id=t AND id=(v->>'printer_id')::uuid FOR UPDATE;
 IF st.id IS NULL OR p.id IS NULL OR NOT st.enabled OR NOT p.enabled OR p.format<>'pdf' OR p.station_id IS DISTINCT FROM st.id OR st.version::text IS DISTINCT FROM v->>'station_version' OR p.version::text IS DISTINCT FROM v->>'printer_version' THEN RAISE EXCEPTION 'Stanowisko lub drukarka zmieniły się' USING ERRCODE='23514';END IF;
 RETURN jsonb_build_object('station',jsonb_build_object('id',st.id,'version',st.version::text,'code',st.code,'label',st.label),'printer',print_job_printer_head(to_jsonb(p)),'copies',v->'copies','enabled',v->'enabled','scope','one_existing_demo_or_dpd_label');END $$;
CREATE FUNCTION packed_label_print_preview(v jsonb,uid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p packed_label_print_previews;s jsonb;rh text;n bigint;BEGIN
 PERFORM packed_label_print_require(uid,true);PERFORM print_job_lock();rh:=print_job_hash(jsonb_build_object('actor',uid,'request',v));
 SELECT * INTO p FROM packed_label_print_previews WHERE tenant_id=t AND client_key=(v->>'client_key')::uuid;
 IF p.id IS NOT NULL THEN IF p.actor_id IS DISTINCT FROM uid OR p.request_hash IS DISTINCT FROM rh THEN RAISE EXCEPTION 'Klucz podglądu ma inną treść' USING ERRCODE='23514';END IF;RETURN (to_jsonb(p)-ARRAY['tenant_id','actor_id','request_hash'])||jsonb_build_object('expected_version',p.expected_version::text);END IF;
 IF (SELECT count(*) FROM packed_label_print_previews WHERE tenant_id=t)>=2000 THEN RAISE EXCEPTION 'Limit podglądów druku' USING ERRCODE='23514';END IF;
 n:=coalesce((SELECT max(version) FROM packed_label_print_configurations WHERE tenant_id=t AND station_id=(v->'settings'->>'station_id')::uuid),0);
 IF n::text IS DISTINCT FROM v->>'expected_version' THEN RAISE EXCEPTION 'Zgoda stanowiska zmieniła wersję' USING ERRCODE='23514';END IF;
 s:=packed_label_print_configuration_frame(v->'settings');
 INSERT INTO packed_label_print_previews(id,tenant_id,actor_id,client_key,request_hash,scope_hash,expected_version,settings,snapshot,expires_at) VALUES(gen_random_uuid(),t,uid,(v->>'client_key')::uuid,rh,print_job_hash(jsonb_build_object('settings',v->'settings','snapshot',s,'expected_version',n::text)),n,v->'settings',s,clock_timestamp()+interval '15 minutes') RETURNING * INTO p;
 PERFORM packed_label_print_require(uid,true,true);RETURN (to_jsonb(p)-ARRAY['tenant_id','actor_id','request_hash'])||jsonb_build_object('expected_version',p.expected_version::text);END $$;
CREATE FUNCTION packed_label_print_approve(pid uuid,v jsonb,uid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p packed_label_print_previews;cfg packed_label_print_configurations;s jsonb;BEGIN
 PERFORM packed_label_print_require(uid,true);PERFORM print_job_lock();SELECT * INTO p FROM packed_label_print_previews WHERE tenant_id=t AND id=pid FOR UPDATE;
 IF p.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono zgody druku' USING ERRCODE='P0002';END IF;
 IF p.actor_id IS DISTINCT FROM uid OR p.scope_hash IS DISTINCT FROM v->>'scope_hash' OR v->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Zgoda nie obejmuje tego podglądu' USING ERRCODE='23514';END IF;
 IF p.configuration_id IS NOT NULL THEN IF p.commit_key IS DISTINCT FROM(v->>'client_key')::uuid THEN RAISE EXCEPTION 'Zgoda została już zapisana innym kluczem' USING ERRCODE='23514';END IF;SELECT * INTO cfg FROM packed_label_print_configurations WHERE tenant_id=t AND id=p.configuration_id;RETURN jsonb_build_object('configuration',(to_jsonb(cfg)-ARRAY['tenant_id','approved_by'])||jsonb_build_object('version',cfg.version::text),'reused',true);END IF;
 IF p.expires_at<=clock_timestamp() OR coalesce((SELECT max(version) FROM packed_label_print_configurations WHERE tenant_id=t AND station_id=(p.settings->>'station_id')::uuid),0)<>p.expected_version THEN RAISE EXCEPTION 'Podgląd zgody wygasł lub zmienił wersję' USING ERRCODE='23514';END IF;
 s:=packed_label_print_configuration_frame(p.settings);IF s IS DISTINCT FROM p.snapshot THEN RAISE EXCEPTION 'Konfiguracja druku zmieniła się od podglądu' USING ERRCODE='23514';END IF;
 INSERT INTO packed_label_print_configurations(id,tenant_id,station_id,version,approved_by,preview_id,enabled,settings,snapshot) VALUES(gen_random_uuid(),t,(p.settings->>'station_id')::uuid,p.expected_version+1,uid,p.id,(p.settings->>'enabled')::boolean,p.settings,p.snapshot) RETURNING * INTO cfg;
 UPDATE packed_label_print_previews SET commit_key=(v->>'client_key')::uuid,configuration_id=cfg.id WHERE tenant_id=t AND id=p.id;
 PERFORM packed_label_print_require(uid,true,true);RETURN jsonb_build_object('configuration',(to_jsonb(cfg)-ARRAY['tenant_id','approved_by'])||jsonb_build_object('version',cfg.version::text),'reused',false);END $$;
CREATE FUNCTION packed_label_print_capture(rid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;r packing_receipts;cfg packed_label_print_configurations;st uuid;i uuid;BEGIN
 IF packed_label_print_guards() IS NOT TRUE THEN RAISE EXCEPTION 'Automatyczny druk jest niekompletny' USING ERRCODE='55000';END IF;
 SELECT * INTO r FROM packing_receipts WHERE tenant_id=t AND id=rid;
 IF r.id IS NULL OR r.kind<>'finish' OR r.result->>'session_id' IS NULL OR NOT EXISTS(SELECT 1 FROM packing_sessions ps WHERE ps.tenant_id=t AND ps.id=(r.result->>'session_id')::uuid AND ps.order_id=r.order_id AND ps.owner_id=r.actor_id AND ps.state='finished') THEN RAISE EXCEPTION 'Brak rzeczywistego zakończenia pakowania w tej transakcji' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM orders WHERE tenant_id=t AND id=r.order_id AND status='packed') OR NOT EXISTS(SELECT 1 FROM order_packing_profiles WHERE tenant_id=t AND order_id=r.order_id AND receipt_id=r.id AND revision=r.profile_revision) THEN RAISE EXCEPTION 'Brak pełnego natywnego wyniku pakowania' USING ERRCODE='23514';END IF;
 st:=(r.full_snapshot->'station'->>'id')::uuid;
 SELECT * INTO cfg FROM packed_label_print_configurations WHERE tenant_id=t AND station_id=st ORDER BY version DESC LIMIT 1;
 IF cfg.id IS NULL OR NOT cfg.enabled THEN RETURN NULL;END IF;
 PERFORM packed_label_print_require(cfg.approved_by,true,true);
 IF (print_job_access(r.actor_id,NULL,false,true)->>'allowed')::boolean IS NOT TRUE THEN RAISE EXCEPTION 'Autor pakowania nie ma bieżącego dostępu' USING ERRCODE='42501';END IF;
 IF cfg.settings->>'station_version' IS DISTINCT FROM r.full_snapshot->'station'->>'version' THEN RAISE EXCEPTION 'Zgoda dotyczy innej wersji stanowiska' USING ERRCODE='23514';END IF;
 IF (SELECT count(*) FROM packed_label_print_intents WHERE tenant_id=t)>=2000 THEN RAISE EXCEPTION 'Limit historii automatycznego druku' USING ERRCODE='23514';END IF;
 INSERT INTO packed_label_print_intents(id,tenant_id,receipt_id,order_id,station_id,configuration_id,approved_by,state,reason,preview_key,queue_key) VALUES(gen_random_uuid(),t,r.id,r.order_id,st,cfg.id,cfg.approved_by,'waiting','Źródło i aktualna zgoda wymagają sprawdzenia',gen_random_uuid(),gen_random_uuid()) ON CONFLICT(tenant_id,receipt_id) DO NOTHING RETURNING id INTO i;
 RETURN coalesce(i,(SELECT id FROM packed_label_print_intents WHERE tenant_id=t AND receipt_id=r.id));END $$;
CREATE FUNCTION packed_label_print_resolve_frame(iid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;i packed_label_print_intents;cfg packed_label_print_configurations;s shipments;n integer;BEGIN
 IF packed_label_print_guards() IS NOT TRUE THEN RAISE EXCEPTION 'Automatyczny druk jest niekompletny' USING ERRCODE='55000';END IF;
 PERFORM print_job_lock();SELECT * INTO i FROM packed_label_print_intents WHERE tenant_id=t AND id=iid FOR UPDATE;
 IF i.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono oczekiwania na etykietę' USING ERRCODE='P0002';END IF;
 PERFORM packed_label_print_require(i.approved_by,true);
 IF i.state<>'waiting' THEN RETURN jsonb_build_object('intent',to_jsonb(i)-ARRAY['tenant_id','approved_by','preview_key','queue_key'],'ready',false);END IF;
 PERFORM 1 FROM orders WHERE tenant_id=t AND id=i.order_id FOR UPDATE;
 SELECT * INTO cfg FROM packed_label_print_configurations WHERE tenant_id=t AND id=i.configuration_id;
 IF cfg.id IS DISTINCT FROM(SELECT id FROM packed_label_print_configurations WHERE tenant_id=t AND station_id=i.station_id ORDER BY version DESC LIMIT 1) OR NOT cfg.enabled THEN UPDATE packed_label_print_intents SET state='blocked',reason='Zgoda stanowiska została zastąpiona',updated_at=clock_timestamp() WHERE tenant_id=t AND id=i.id;RETURN jsonb_build_object('ready',false);END IF;
 IF EXISTS(SELECT 1 FROM orders WHERE tenant_id=t AND id=i.order_id AND status IN('cancelled','return_initiated','return_received','return_completed')) THEN UPDATE packed_label_print_intents SET state='blocked',reason='Zamówienie nie oczekuje już na wysyłkę',updated_at=clock_timestamp() WHERE tenant_id=t AND id=i.id;RETURN jsonb_build_object('ready',false);END IF;
 SELECT count(*) INTO n FROM shipments WHERE tenant_id=t AND order_id=i.order_id AND status NOT IN('cancelled','voided');
 IF n=0 THEN RETURN jsonb_build_object('ready',false);END IF;
 IF n<>1 THEN UPDATE packed_label_print_intents SET state='blocked',reason='Wiele przesyłek wymaga osobnego zakresu druku',updated_at=clock_timestamp() WHERE tenant_id=t AND id=i.id;RETURN jsonb_build_object('ready',false);END IF;
 SELECT * INTO s FROM shipments WHERE tenant_id=t AND order_id=i.order_id AND status NOT IN('cancelled','voided') FOR UPDATE;
 IF packed_label_print_configuration_frame(cfg.settings) IS DISTINCT FROM cfg.snapshot THEN RAISE EXCEPTION 'Zamrożona konfiguracja druku zmieniła się' USING ERRCODE='23514';END IF;
 IF s.mode<>'demo' AND NOT(s.carrier='DPD Polska' AND EXISTS(SELECT 1 FROM shipping_plans p WHERE p.tenant_id=t AND p.shipment_id=s.id AND p.state IN('ready','dispatched') AND p.result->>'label_base64' IS NOT NULL)) THEN RETURN jsonb_build_object('ready',false);END IF;
 RETURN jsonb_build_object('ready',true,'actor_id',i.approved_by,'shipment_id',s.id,'intent_id',i.id,'queue_key',i.queue_key,'request',(cfg.settings-ARRAY['enabled'])||jsonb_build_object('client_key',i.preview_key,'order_version',(SELECT version::text FROM orders WHERE tenant_id=t AND id=i.order_id)));
END $$;
CREATE FUNCTION packed_label_print_admit(iid uuid,pid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;i packed_label_print_intents;p print_label_previews;cfg packed_label_print_configurations;BEGIN
 SELECT * INTO i FROM packed_label_print_intents WHERE tenant_id=t AND id=iid;
 SELECT * INTO p FROM print_label_previews WHERE tenant_id=t AND id=pid;
 SELECT * INTO cfg FROM packed_label_print_configurations WHERE tenant_id=t AND id=i.configuration_id;
 PERFORM packed_label_print_require(i.approved_by,true);
 IF i.id IS NULL OR i.state<>'waiting' OR p.id IS NULL OR p.order_id IS DISTINCT FROM i.order_id OR p.station_id IS DISTINCT FROM i.station_id OR p.actor_id IS DISTINCT FROM i.approved_by OR p.api_key_id IS NOT NULL OR p.client_key IS DISTINCT FROM i.preview_key OR (p.request-ARRAY['client_key','order_version']) IS DISTINCT FROM(cfg.settings-ARRAY['enabled']) THEN RAISE EXCEPTION 'Podgląd nie należy do zgody przyszłego druku' USING ERRCODE='23514';END IF;
 INSERT INTO packed_label_print_admissions(tenant_id,intent_id,preview_id,approved_by) VALUES(t,i.id,p.id,i.approved_by);END $$;
CREATE FUNCTION packed_label_print_queue_allowed(pid uuid,v jsonb,uid uuid,kid uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;i packed_label_print_intents;a packed_label_print_admissions;cfg packed_label_print_configurations;BEGIN
 PERFORM packed_label_print_require(uid,true,true);
 SELECT * INTO a FROM packed_label_print_admissions WHERE tenant_id=t AND intent_id=(v->>'packed_intent_id')::uuid AND preview_id=pid;
 SELECT * INTO i FROM packed_label_print_intents WHERE tenant_id=t AND id=a.intent_id;
 SELECT * INTO cfg FROM packed_label_print_configurations WHERE tenant_id=t AND id=i.configuration_id;
 IF kid IS NOT NULL OR a.preview_id IS NULL OR a.top_xid IS DISTINCT FROM pg_current_xact_id() OR a.started_at IS DISTINCT FROM transaction_timestamp() OR a.approved_by IS DISTINCT FROM uid OR i.approved_by IS DISTINCT FROM uid OR i.queue_key IS DISTINCT FROM(v->>'client_key')::uuid OR cfg.id IS DISTINCT FROM(SELECT id FROM packed_label_print_configurations WHERE tenant_id=t AND station_id=i.station_id ORDER BY version DESC LIMIT 1) OR NOT cfg.enabled OR (v-ARRAY['client_key','scope_hash','packed_intent_id'])<>'{}'::jsonb THEN RAISE EXCEPTION 'Brak przyjętej zgody automatycznego druku' USING ERRCODE='23514';END IF;
 IF packed_label_print_configuration_frame(cfg.settings) IS DISTINCT FROM cfg.snapshot THEN RAISE EXCEPTION 'Zamrożona konfiguracja druku zmieniła się' USING ERRCODE='23514';END IF;RETURN true;END $$;
CREATE FUNCTION packed_label_print_finish(iid uuid,jid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;i packed_label_print_intents;BEGIN
 SELECT * INTO i FROM packed_label_print_intents WHERE tenant_id=t AND id=iid;
 PERFORM packed_label_print_require(i.approved_by,true,true);
 IF NOT EXISTS(SELECT 1 FROM print_job_label_sources l JOIN packed_label_print_admissions a ON(a.tenant_id,a.preview_id)=(l.tenant_id,l.preview_id) WHERE l.tenant_id=t AND l.job_id=jid AND a.intent_id=iid AND l.request->>'packed_intent_id'=iid::text) THEN RAISE EXCEPTION 'Brak natywnego zadania etykiety' USING ERRCODE='23514';END IF;
 UPDATE packed_label_print_intents SET state='queued',reason=NULL,job_id=jid,updated_at=clock_timestamp() WHERE tenant_id=t AND id=iid AND state='waiting';END $$;
CREATE FUNCTION packed_label_print_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE i packed_label_print_intents;l print_job_label_sources;BEGIN
 SELECT * INTO i FROM packed_label_print_intents WHERE tenant_id=NEW.tenant_id AND id=NEW.intent_id;
 SELECT * INTO l FROM print_job_label_sources WHERE tenant_id=NEW.tenant_id AND preview_id=NEW.preview_id;
 IF i.state IS DISTINCT FROM 'queued' OR l.job_id IS NULL OR l.job_id IS DISTINCT FROM i.job_id OR l.order_id IS DISTINCT FROM i.order_id OR l.actor_id IS DISTINCT FROM i.approved_by OR NEW.top_xid IS DISTINCT FROM pg_current_xact_id() THEN RAISE EXCEPTION 'Automatyczny druk nie osiągnął pełnego natywnego zapisu' USING ERRCODE='23514';END IF;
 PERFORM packed_label_print_queue_allowed(NEW.preview_id,l.request,l.actor_id,l.api_key_id);RETURN NEW;END $$;
CREATE CONSTRAINT TRIGGER packed_label_print_complete AFTER INSERT ON packed_label_print_admissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION packed_label_print_complete();
CREATE FUNCTION packed_label_print_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$BEGIN
 IF TG_OP='DELETE' OR TG_TABLE_NAME IN('packed_label_print_configurations','packed_label_print_admissions') THEN RAISE EXCEPTION 'Dowód przyszłego druku jest niezmienny' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='packed_label_print_previews' THEN IF OLD.configuration_id IS NOT NULL OR (to_jsonb(OLD)-ARRAY['commit_key','configuration_id']) IS DISTINCT FROM(to_jsonb(NEW)-ARRAY['commit_key','configuration_id']) OR NEW.configuration_id IS NULL OR NEW.commit_key IS NULL THEN RAISE EXCEPTION 'Podgląd zgody jest niezmienny' USING ERRCODE='23514';END IF;
 ELSE IF OLD.state<>'waiting' OR NEW.state NOT IN('queued','blocked') OR (to_jsonb(OLD)-ARRAY['state','reason','job_id','updated_at']) IS DISTINCT FROM(to_jsonb(NEW)-ARRAY['state','reason','job_id','updated_at']) THEN RAISE EXCEPTION 'Zamrożony zamiar druku jest niezmienny' USING ERRCODE='23514';END IF;END IF;RETURN NEW;END $$;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['packed_label_print_previews','packed_label_print_configurations','packed_label_print_intents','packed_label_print_admissions'] LOOP EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION packed_label_print_immutable()',n);END LOOP;END $$;
CREATE OR REPLACE FUNCTION label_print_queue(pid uuid,v jsonb,b64 text,uid uuid,kid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid; p print_label_previews; a print_label_assets; j print_jobs; l print_job_label_sources; f jsonb; config jsonb; rh text; outv jsonb; ts timestamptz:=clock_timestamp();
BEGIN
 PERFORM label_print_require(uid,kid,true); PERFORM print_job_lock();
 IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR (CASE WHEN v?'packed_intent_id' THEN packed_label_print_queue_allowed(pid,v,uid,kid) ELSE (v-ARRAY['client_key','scope_hash','confirmed'])='{}'::jsonb AND v->'confirmed'='true'::jsonb END) IS NOT TRUE THEN RAISE EXCEPTION 'Niepoprawna zgoda kolejki etykiety' USING ERRCODE='23514'; END IF;
 rh:=print_job_hash(jsonb_build_object('tenant_id',t,'actor_id',uid,'api_key_id',kid,'preview_id',pid,'request',v));
 SELECT * INTO l FROM print_job_label_sources WHERE tenant_id=t AND client_key=(v->>'client_key')::uuid;
 IF l.job_id IS NOT NULL THEN
  IF l.preview_id IS DISTINCT FROM pid OR l.actor_id IS DISTINCT FROM uid OR l.api_key_id IS DISTINCT FROM kid OR l.request_hash IS DISTINCT FROM rh THEN RAISE EXCEPTION 'Klucz kolejki etykiety ma inną treść' USING ERRCODE='23514'; END IF;
  outv:=print_job_replay(l.client_key,rh,uid,kid,'job_create',l.job_id); IF outv IS NULL THEN RAISE EXCEPTION 'Brak potwierdzenia kolejki etykiety' USING ERRCODE='23514'; END IF; RETURN outv||jsonb_build_object('preview_id',pid);
 END IF;
 SELECT * INTO p FROM print_label_previews WHERE tenant_id=t AND id=pid;
 IF p.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono podglądu etykiety' USING ERRCODE='P0002'; END IF;
 IF p.actor_id IS DISTINCT FROM uid OR p.api_key_id IS DISTINCT FROM kid OR p.scope_hash IS DISTINCT FROM v->>'scope_hash' OR p.expires_at<=clock_timestamp() OR EXISTS(SELECT 1 FROM print_job_label_sources WHERE tenant_id=t AND preview_id=pid) THEN RAISE EXCEPTION 'Podgląd etykiety jest nieaktualny lub już użyty' USING ERRCODE='23514'; END IF;
 f:=label_print_frame(p.shipment_id,uid,kid); config:=label_print_configuration(p.request,f->'order_snapshot');
 SELECT * INTO a FROM print_label_assets WHERE tenant_id=t AND id=p.asset_id;
 IF a.source_frame IS DISTINCT FROM f->'source_frame' OR config IS DISTINCT FROM p.payload-ARRAY['id','shipment_id','order_id','asset_id','source_kind','source_snapshot','format','content_sha256','content_bytes','created_at','expires_at'] OR print_job_hash(p.payload) IS DISTINCT FROM p.scope_hash OR print_job_content_valid(b64,'pdf') IS NOT TRUE OR encode(sha256(decode(b64,'base64')),'hex') IS DISTINCT FROM a.content_sha256 OR octet_length(decode(b64,'base64')) IS DISTINCT FROM a.content_bytes OR (a.source_kind='dpd_cached' AND b64 IS DISTINCT FROM f->>'content_base64') THEN RAISE EXCEPTION 'Etykieta lub zakres podglądu zmieniły się' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM print_job_events WHERE tenant_id=t AND client_key=(v->>'client_key')::uuid) THEN RAISE EXCEPTION 'Klucz polecenia drukowania ma inną treść' USING ERRCODE='23514'; END IF;
 j.id:=gen_random_uuid(); j.tenant_id:=t; j.order_id:=p.order_id; j.station_id:=p.station_id; j.printer_id:=p.printer_id; j.actor_id:=uid; j.api_key_id:=kid; j.client_key:=(v->>'client_key')::uuid; j.request_hash:=rh; j.order_snapshot:=p.payload->'order_snapshot'; j.station_snapshot:=p.payload->'station_snapshot'; j.printer_snapshot:=p.payload->'printer_snapshot'; j.source_kind:='shipment_label'; j.format:='pdf'; j.copies:=(p.payload->>'copies')::integer; j.content_base64:=b64; j.content_sha256:=a.content_sha256; j.content_bytes:=a.content_bytes; j.version:=1; j.state:='queued'; j.created_at:=ts; j.updated_at:=ts;
 INSERT INTO print_job_label_sources(tenant_id,job_id,preview_id,asset_id,shipment_id,order_id,actor_id,api_key_id,client_key,request_hash,request,created_at) VALUES(t,j.id,pid,a.id,p.shipment_id,p.order_id,uid,kid,j.client_key,rh,v,ts);
 outv:=print_job_event(gen_random_uuid(),j.id,NULL,uid,kid,j.client_key,rh,'job_create',NULL,print_job_head(to_jsonb(j)),jsonb_build_object('preview_id',pid,'shipment_id',p.shipment_id,'asset_id',a.id,'source_kind',a.source_kind));
 INSERT INTO print_jobs SELECT j.*; PERFORM label_print_budget(); PERFORM label_print_require(uid,kid,true); RETURN outv||jsonb_build_object('preview_id',pid);
END $$;
CREATE OR REPLACE FUNCTION label_print_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE p print_label_previews; a print_label_assets; j print_jobs; f jsonb; cfg jsonb; t uuid; jid uuid; BEGIN
 t:=NEW.tenant_id;
 IF t IS DISTINCT FROM nullif(current_setting('app.tenant_id',true),'')::uuid THEN RAISE EXCEPTION 'Niepoprawny tenant etykiety' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='print_jobs' THEN
  IF NEW.source_kind<>'shipment_label' THEN RETURN NEW; END IF;
  j:=NEW;
  SELECT * INTO p FROM print_label_previews WHERE tenant_id=t AND id=(SELECT preview_id FROM print_job_label_sources WHERE tenant_id=t AND job_id=NEW.id);
 ELSE
  SELECT * INTO p FROM print_label_previews WHERE tenant_id=t AND id=NEW.preview_id;
  SELECT * INTO j FROM print_jobs WHERE tenant_id=t AND id=NEW.job_id;
  IF NEW.top_xid IS DISTINCT FROM pg_current_xact_id() OR NEW.transaction_started_at IS DISTINCT FROM transaction_timestamp() OR p.actor_id IS DISTINCT FROM NEW.actor_id OR p.api_key_id IS DISTINCT FROM NEW.api_key_id OR NEW.asset_id IS DISTINCT FROM p.asset_id OR NEW.shipment_id IS DISTINCT FROM p.shipment_id OR NEW.order_id IS DISTINCT FROM p.order_id OR NEW.request_hash IS DISTINCT FROM print_job_hash(jsonb_build_object('tenant_id',t,'actor_id',NEW.actor_id,'api_key_id',NEW.api_key_id,'preview_id',p.id,'request',NEW.request)) OR NEW.request->>'scope_hash' IS DISTINCT FROM p.scope_hash OR (CASE WHEN NEW.request?'packed_intent_id' THEN packed_label_print_queue_allowed(p.id,NEW.request,NEW.actor_id,NEW.api_key_id) ELSE NEW.request->'confirmed'='true'::jsonb END) IS NOT TRUE THEN RAISE EXCEPTION 'Niepoprawna zgoda źródłowej etykiety' USING ERRCODE='23514'; END IF;
 END IF;
 IF p.id IS NULL OR j.id IS NULL THEN RAISE EXCEPTION 'Zadanie etykiety wymaga pełnego powiązania' USING ERRCODE='23514'; END IF;
 SELECT * INTO a FROM print_label_assets WHERE tenant_id=t AND id=p.asset_id;
 IF j.source_kind<>'shipment_label' OR j.order_id IS DISTINCT FROM p.order_id OR j.station_id IS DISTINCT FROM p.station_id OR j.printer_id IS DISTINCT FROM p.printer_id OR j.order_snapshot IS DISTINCT FROM p.payload->'order_snapshot' OR j.station_snapshot IS DISTINCT FROM p.payload->'station_snapshot' OR j.printer_snapshot IS DISTINCT FROM p.payload->'printer_snapshot' OR j.content_sha256 IS DISTINCT FROM a.content_sha256 OR j.content_bytes IS DISTINCT FROM a.content_bytes OR j.copies IS DISTINCT FROM (p.payload->>'copies')::integer OR j.format<>'pdf' THEN RAISE EXCEPTION 'Zadanie nie odpowiada zatwierdzonej etykiecie' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='print_job_label_sources' THEN
  IF j.actor_id IS DISTINCT FROM NEW.actor_id OR j.api_key_id IS DISTINCT FROM NEW.api_key_id OR j.client_key IS DISTINCT FROM NEW.client_key OR j.request_hash IS DISTINCT FROM NEW.request_hash OR p.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Niepoprawny principal źródłowej etykiety' USING ERRCODE='23514'; END IF;
  f:=label_print_frame(p.shipment_id,NEW.actor_id,NEW.api_key_id); cfg:=label_print_configuration(p.request,f->'order_snapshot');
  IF a.source_frame IS DISTINCT FROM f->'source_frame' OR cfg IS DISTINCT FROM p.payload-ARRAY['id','shipment_id','order_id','asset_id','source_kind','source_snapshot','format','content_sha256','content_bytes','created_at','expires_at'] OR print_job_hash(p.payload) IS DISTINCT FROM p.scope_hash THEN RAISE EXCEPTION 'Końcowe źródło etykiety zmieniło się' USING ERRCODE='23514'; END IF;
  PERFORM label_print_require(NEW.actor_id,NEW.api_key_id,true);
 END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION packed_label_print_capture_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN IF NEW.kind='finish' THEN PERFORM packed_label_print_capture(NEW.id);END IF;RETURN NEW;END $$;
CREATE CONSTRAINT TRIGGER packed_label_print_capture AFTER INSERT ON packing_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION packed_label_print_capture_trigger();
CREATE FUNCTION packed_label_print_fingerprint() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object(
 'capture_trigger',(SELECT jsonb_build_object('definition',pg_get_triggerdef(g.oid),'enabled',g.tgenabled) FROM pg_trigger g WHERE g.tgrelid='packing_receipts'::regclass AND g.tgname='packed_label_print_capture' AND g.tgfoid='packed_label_print_capture_trigger()'::regprocedure),'relations',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,
 'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a),
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',x.attname,'type',format_type(x.atttypid,x.atttypmod),'notnull',x.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(z.grantor),'grantee',CASE WHEN z.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(z.grantee) END,'privilege',z.privilege_type,'grantable',z.is_grantable) ORDER BY pg_get_userbyid(z.grantor),CASE WHEN z.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(z.grantee) END,z.privilege_type,z.is_grantable) FROM aclexplode(x.attacl) z)) ORDER BY x.attnum) FROM pg_attribute x LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(x.attrelid,x.attnum) WHERE x.attrelid=c.oid AND x.attnum>0 AND NOT x.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid),'valid',k.convalidated) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),
 'policies',(SELECT jsonb_agg(jsonb_build_object('name',p.polname,'cmd',p.polcmd,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid),'roles',(SELECT jsonb_agg(CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END ORDER BY CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END) FROM unnest(p.polroles) r)) ORDER BY p.polname) FROM pg_policy p WHERE p.polrelid=c.oid),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('name',g.tgname,'definition',pg_get_triggerdef(g.oid),'enabled',g.tgenabled) ORDER BY g.tgname) FROM pg_trigger g WHERE g.tgrelid=c.oid AND NOT g.tgisinternal)) ORDER BY c.relname) FROM pg_class c WHERE c.oid=ANY(ARRAY['packed_label_print_previews','packed_label_print_configurations','packed_label_print_intents','packed_label_print_admissions','packed_label_print_manifest','print_printers','print_jobs','print_job_events','print_label_assets','print_label_previews','print_job_label_sources','packing_stations','packing_cartons','packing_policies','packing_sessions','packing_operations','packing_previews','packing_receipts','order_packing_profiles']::regclass[])),
 'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'def',pg_get_functiondef(p.oid),'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) ORDER BY p.proname,p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname=ANY(ARRAY['packed_label_print_require', 'packed_label_print_configuration_frame', 'packed_label_print_preview', 'packed_label_print_approve', 'packed_label_print_capture', 'packed_label_print_resolve_frame', 'packed_label_print_admit', 'packed_label_print_queue_allowed', 'packed_label_print_finish', 'packed_label_print_complete', 'packed_label_print_immutable', 'label_print_queue', 'label_print_guard', 'packed_label_print_capture_trigger', 'print_job_installed', 'print_job_access', 'print_job_require', 'print_job_hash', 'print_job_head', 'print_job_printer_head', 'print_job_lock', 'print_job_budget', 'print_job_content_valid', 'print_job_replay', 'print_job_event', 'print_job_printer_write', 'print_job_create', 'print_job_command', 'print_job_content', 'print_job_immutable', 'print_job_guard', 'print_job_complete', 'print_job_guards', 'label_print_installed', 'label_print_require', 'label_print_frame', 'label_print_configuration', 'label_print_preview_replay', 'label_print_store_preview', 'label_print_asset', 'label_print_queue_replay', 'label_print_budget', 'label_print_immutable', 'label_print_budget_trigger', 'label_print_seal', 'label_print_guards', 'packing_current_role', 'packing_key_grant', 'packing_operator_names', 'packing_fulfillment_snapshot', 'packing_fulfillment_hash', 'packing_row_guard', 'packing_budget_guard', 'packing_receipt_after_guard', 'packing_insert_admission', 'packing_scope_guard', 'packing_update_admission'])) )::text,'UTF8')),'hex') $$;
CREATE FUNCTION packed_label_print_guards() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN
 IF current_setting('session_replication_role')<>'origin' OR NOT EXISTS(SELECT 1 FROM migrations WHERE name='156_packed_label_print') OR EXISTS(SELECT 1 FROM unnest(ARRAY['packed_label_print_previews','packed_label_print_configurations','packed_label_print_intents','packed_label_print_admissions','packed_label_print_manifest','print_printers','print_jobs','print_job_events','print_label_assets','print_label_previews','print_job_label_sources','packing_stations','packing_cartons','packing_policies','packing_sessions','packing_operations','packing_previews','packing_receipts','order_packing_profiles']) n WHERE to_regclass(n) IS NULL) OR EXISTS(SELECT 1 FROM unnest(ARRAY['packed_label_print_require', 'packed_label_print_configuration_frame', 'packed_label_print_preview', 'packed_label_print_approve', 'packed_label_print_capture', 'packed_label_print_resolve_frame', 'packed_label_print_admit', 'packed_label_print_queue_allowed', 'packed_label_print_finish', 'packed_label_print_complete', 'packed_label_print_immutable', 'label_print_queue', 'label_print_guard', 'packed_label_print_capture_trigger', 'print_job_installed', 'print_job_access', 'print_job_require', 'print_job_hash', 'print_job_head', 'print_job_printer_head', 'print_job_lock', 'print_job_budget', 'print_job_content_valid', 'print_job_replay', 'print_job_event', 'print_job_printer_write', 'print_job_create', 'print_job_command', 'print_job_content', 'print_job_immutable', 'print_job_guard', 'print_job_complete', 'print_job_guards', 'label_print_installed', 'label_print_require', 'label_print_frame', 'label_print_configuration', 'label_print_preview_replay', 'label_print_store_preview', 'label_print_asset', 'label_print_queue_replay', 'label_print_budget', 'label_print_immutable', 'label_print_budget_trigger', 'label_print_seal', 'label_print_guards', 'packing_current_role', 'packing_key_grant', 'packing_operator_names', 'packing_fulfillment_snapshot', 'packing_fulfillment_hash', 'packing_row_guard', 'packing_budget_guard', 'packing_receipt_after_guard', 'packing_insert_admission', 'packing_scope_guard', 'packing_update_admission','packed_label_print_fingerprint','packed_label_print_guards']) n WHERE NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname=n)) THEN RETURN false;END IF;
 RETURN label_print_guards() AND print_job_guards() AND (SELECT fingerprint=packed_label_print_fingerprint() FROM packed_label_print_manifest WHERE singleton);END $$;
REVOKE ALL ON FUNCTION packed_label_print_fingerprint(),packed_label_print_guards() FROM PUBLIC,dyna_app;
GRANT EXECUTE ON FUNCTION packed_label_print_guards() TO dyna_app;
DO $$DECLARE p regprocedure;BEGIN FOR p IN SELECT oid::regprocedure FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'packed_label_print_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,dyna_app',p);END LOOP;END $$;
GRANT EXECUTE ON FUNCTION packed_label_print_guards(),packed_label_print_preview(jsonb,uuid),packed_label_print_approve(uuid,jsonb,uuid),packed_label_print_resolve_frame(uuid),packed_label_print_admit(uuid,uuid),packed_label_print_finish(uuid,uuid),packed_label_print_require(uuid,boolean,boolean) TO dyna_app;
INSERT INTO packed_label_print_manifest VALUES(true,packed_label_print_fingerprint());
